def solve(g):
    n=len(g)
    parent=list(range(n*n))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def uni(a,b):
        a,b=find(a),find(b)
        if a!=b: parent[b]=a
    for r in range(n):
        for c in range(n):
            uni(r*n+c, c*n+r)                 # transpose symmetry
            if 31-r<n: uni(r*n+c,(31-r)*n+c)  # row pair a+b=31
            if 31-c<n: uni(r*n+c, r*n+(31-c)) # col pair
    # assign: any cell whose class has a non-6 value
    val={}
    for r in range(n):
        for c in range(n):
            v=g[r][c]
            if v!=6: val.setdefault(find(r*n+c),v)
    res=[row[:] for row in g]
    miss=[]
    for r in range(n):
        for c in range(n):
            if res[r][c]==6:
                rt=find(r*n+c)
                if rt in val: res[r][c]=val[rt]
                else: miss.append((r,c))
    return res,miss
